if (points.empty()) {
    return BoundingBox2{Point2d{0, 0}, Point2d{0, 0}};
}

Point2d minPt = points[0];
Point2d maxPt = points[0];

for (const auto& point : points) {
    if (point.x < minPt.x) minPt.x = point.x;
    if (point.y < minPt.y) minPt.y = point.y;
    if (point.x > maxPt.x) maxPt.x = point.x;
    if (point.y > maxPt.y) maxPt.y = point.y;
}

return BoundingBox2{minPt, maxPt};
// END_CODE

